package com.mfg.srm.entity;import jakarta.persistence.*;import lombok.*;import java.math.*;import java.time.*;
@Entity @Table(name="srm_purchase_order",catalog="src_srm") @Getter @Setter @NoArgsConstructor public class PurchaseOrder{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="purchase_order_no")private String purchaseOrderNo;@Column(name="supplier_code")private String supplierCode;@Column(name="supplier_name")private String supplierName;@Column(name="material_code")private String materialCode;@Column(name="material_name")private String materialName;@Column(name="order_qty")private BigDecimal orderQty;@Column(name="received_qty")private BigDecimal receivedQty=BigDecimal.ZERO;@Column(name="unit_code")private String unitCode;@Column(name="unit_price")private BigDecimal unitPrice;@Column(name="total_amount")private BigDecimal totalAmount;@Column(name="order_date")private LocalDate orderDate;@Column(name="promised_date")private LocalDate promisedDate;@Column(name="expected_date")private LocalDate expectedDate;@Column(name="order_status")private String status="CREATED";@Column(name="prod_order_no")private String prodOrderNo;@Column(name="purchase_user")private String purchaseUser;}
